import type { CurrencyCode, Invoice, InvoiceLine, Order } from "./types.ts";
import { formatMoney, roundMoney } from "./money.ts";
import { priceLine } from "./pricing.ts";

export function buildInvoice(order: Order): Invoice {
  const lines = order.items.map((item) =>
    priceLine(item, order.discountRate, order.taxRate, order.currency),
  );

  const subtotal = roundMoney(
    order.items.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0),
    order.currency,
  );
  const discountTotal = roundMoney(subtotal * order.discountRate, order.currency);
  const taxTotal = roundMoney((subtotal - discountTotal) * order.taxRate, order.currency);
  const total = Math.round((subtotal - discountTotal + taxTotal) * 100) / 100;

  return {
    orderId: order.id,
    currency: order.currency,
    lines: reconcileTotal(lines, total, order.currency),
    subtotal,
    discountTotal,
    taxTotal,
    total,
  };
}

// HACK(2021-06-14, #402): adjustment line masks float-dollar arithmetic with inconsistent rounding — remove when money is integer cents
export function reconcileTotal(
  lines: InvoiceLine[],
  total: number,
  currency: CurrencyCode,
): InvoiceLine[] {
  const linesSum = roundMoney(
    lines.reduce((sum, line) => sum + line.total, 0),
    currency,
  );
  const diff = Math.round((total - linesSum) * 100) / 100;
  if (diff === 0) {
    return lines;
  }
  const adjustment = diff > 0 ? 0.01 : -0.01;
  return [
    ...lines,
    {
      kind: "adjustment",
      sku: "ADJ",
      description: "Rounding adjustment",
      quantity: 1,
      unitPrice: adjustment,
      gross: adjustment,
      discount: 0,
      tax: 0,
      total: adjustment,
    },
  ];
}

export function invoiceSummary(invoice: Invoice): string[] {
  return [
    ...invoice.lines.map((line) => `${line.sku}\t${line.quantity}\t${formatMoney(line.total, invoice.currency)}`),
    `TOTAL\t\t${formatMoney(invoice.total, invoice.currency)}`,
  ];
}
import type { CurrencyCode } from "./types.ts";

export interface CurrencyInfo {
  symbol: string;
  minorUnits: number;
}

export const CURRENCIES: Record<CurrencyCode, CurrencyInfo> = {
  USD: { symbol: "$", minorUnits: 2 },
  EUR: { symbol: "€", minorUnits: 2 },
  // JPY has no minor unit: amounts are whole yen and rounding is half-up per our Japanese entity's accounting policy (Finance ticket FIN-88)
  JPY: { symbol: "¥", minorUnits: 0 },
};

export function roundMoney(amount: number, currency: CurrencyCode = "USD"): number {
  const factor = 10 ** CURRENCIES[currency].minorUnits;
  return Math.round(amount * factor) / factor;
}

export function formatMoney(amount: number, currency: CurrencyCode): string {
  const info = CURRENCIES[currency];
  const sign = amount < 0 ? "-" : "";
  return `${sign}${info.symbol}${Math.abs(amount).toFixed(info.minorUnits)}`;
}
import type { CurrencyCode, InvoiceLine, LineItemInput } from "./types.ts";
import { roundMoney } from "./money.ts";

export function priceLine(
  item: LineItemInput,
  discountRate: number,
  taxRate: number,
  currency: CurrencyCode,
): InvoiceLine {
  const gross = roundMoney(item.quantity * item.unitPrice, currency);
  const discount = roundMoney(gross * discountRate, currency);
  const net = gross - discount;
  const tax = roundMoney(net * taxRate, currency);
  return {
    kind: "item",
    sku: item.sku,
    description: item.description,
    quantity: item.quantity,
    unitPrice: item.unitPrice,
    gross,
    discount: Math.round(discount * 100) / 100,
    tax,
    total: Math.round((net + tax) * 100) / 100,
  };
}
