  const invoice = buildInvoice({
    id: "ORD-1001",
    currency: "USD",
    discountRate: 0,
    taxRate: 0,
    items: [
      { sku: "MUG-01", description: "Coffee mug", quantity: 2, unitPrice: 8 },
      { sku: "TEE-02", description: "T-shirt", quantity: 1, unitPrice: 15.5 },
